import 'dart:async';import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:get/get.dart';import 'package:mdc_card/moduls/add_card/card_controller/card_controller.dart';import 'package:webview_flutter/webview_flutter.dart';class WebViewCheck extends StatelessWidget {  String? url;  final Completer<WebViewController> _controller =      Completer<WebViewController>();  WebViewCheck(this.url, {Key? key}) : super(key: key);  @override  Widget build(BuildContext context) {    return Scaffold(      appBar: AppBar(        title: Text(          'Payment'.tr,          style: TextStyle(fontSize: 18.sp, color: Colors.white),        ),        leading: IconButton(          onPressed: () {            Get.back();          },          icon: const Icon(            Icons.arrow_back_ios,            color: Colors.white,          ),        ),      ),      body: SafeArea(child: GetBuilder<CardController>(builder: (logic) {        return WebView(          initialUrl: url!,          javascriptMode: JavascriptMode.unrestricted,          onWebViewCreated: (WebViewController webViewController) {            _controller.complete(webViewController);          },          onProgress: (int progress) {            //    print('WebView is loading (progress : $progress%)');          },          javascriptChannels: const <JavascriptChannel>{            // _toasterJavascriptChannel(context),          },          navigationDelegate: (NavigationRequest request) {            if (request.url.startsWith('https://www.youtube.com/')) {              print('blocking navigation to $request}');              return NavigationDecision.prevent;            }            print('allowing navigation to ${request.url}');            if (request.url.split('?').last.split('=').first == "status") {              print(request.url.split('?').last.split('=').last);              logic.redirect = request.url.split('?').last.split('=').last;              Get.back();              Get.back();            }            return NavigationDecision.navigate;          },          onPageStarted: (String url) {            print('Page started loading: $url');          },          onPageFinished: (String url) {            print('Page finished loading: $url');          },          gestureNavigationEnabled: true,          backgroundColor: const Color(0x00000000),        );      })),    );  }}